  /**
   * @method
   * @name delta#fetchLedger
   * @description fetch the history of changes, actions done by the user or
   * operations that altered the balance of the user
   * @see https://docs.delta.exchange/#get-wallet-transactions
   * @param {string} [code] unified currency code, default is undefined
   * @param {int} [since] timestamp in ms of the earliest ledger entry, default
   * is undefined
   * @param {int} [limit] max number of ledger entries to return, default is
   * undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ledger structure]{@link
   * https://docs.ccxt.com/?id=ledger-entry-structure}
   */
  std::shared_future<std::any>
  fetchLedger(std::any code = std::any{}, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 awaitValue(this->loadMarkets());
                 std::any request = ccxt::dict{};
                 std::any currency = std::any{};
                 if (isTrue(!isEqual(code, std::any{}))) {
                   currency = this->currency(code);
                   ::setValue(request, std::string("asset_id"),
                              ::getValue(currency, std::string("numericId")));
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("page_size"), limit);
                 }
                 std::any response =
                     awaitValue(this->privateGetWalletTransactions(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "meta":{"after":null,"before":null,"limit":10,"total_count":1},
                 //         "result":[
                 //             {
                 //                 "amount":"29.889184",
                 //                 "asset_id":5,
                 //                 "balance":"29.889184",
                 //                 "created_at":"2020-11-15T21:25:01Z",
                 //                 "meta_data":{
                 //                     "deposit_id":3884,
                 //                     "transaction_id":"0x41a60174849828530abb5008e98fc63c9b598288743ec4ba9620bcce900a3b8d"
                 //                 },
                 //                 "transaction_type":"deposit",
                 //                 "user_id":22142,
                 //                 "uuid":"70bb5679da3c4637884e2dc63efaa846"
                 //             }
                 //         ],
                 //         "success":true
                 //     }
                 //
                 std::any result = this->safeList(
                     response, std::string("result"), ccxt::list{});
                 return this->parseLedger(result, currency, since, limit);
               })
        .share();
  }

  virtual std::any parseLedgerEntryType(std::any type) {
    std::any types = ccxt::dict{
        {std::string("pnl"), std::string("pnl")},
        {std::string("deposit"), std::string("transaction")},
        {std::string("withdrawal"), std::string("transaction")},
        {std::string("commission"), std::string("fee")},
        {std::string("conversion"), std::string("trade")},
        {std::string("referral_bonus"), std::string("referral")},
        {std::string("commission_rebate"), std::string("rebate")},
    };
    return this->safeString(types, type, type);
  }

  std::any parseLedgerEntry(std::any item,
                            std::any currency = std::any{}) override {
    //
    //     {
    //         "amount":"29.889184",
    //         "asset_id":5,
    //         "balance":"29.889184",
    //         "created_at":"2020-11-15T21:25:01Z",
    //         "meta_data":{
    //             "deposit_id":3884,
    //             "transaction_id":"0x41a60174849828530abb5008e98fc63c9b598288743ec4ba9620bcce900a3b8d"
    //         },
    //         "transaction_type":"deposit",
    //         "user_id":22142,
    //         "uuid":"70bb5679da3c4637884e2dc63efaa846"
    //     }
    //
    std::any id = this->safeString(item, std::string("uuid"));
    std::any direction = std::any{};
    std::any account = std::any{};
    std::any metaData =
        this->safeDict(item, std::string("meta_data"), ccxt::dict{});
    std::any referenceId =
        this->safeString(metaData, std::string("transaction_id"));
    std::any referenceAccount = std::any{};
    std::any type = this->safeString(item, std::string("transaction_type"));
    if (isTrue(
            isTrue(
                isTrue(
                    isTrue(
                        isTrue(
                            isTrue((isEqual(type, std::string("deposit")))) ||
                            isTrue((isEqual(
                                type, std::string("commission_rebate"))))) ||
                        isTrue(
                            (isEqual(type, std::string("referral_bonus"))))) ||
                    isTrue((isEqual(type, std::string("pnl"))))) ||
                isTrue(
                    (isEqual(type, std::string("withdrawal_cancellation"))))) ||
            isTrue((isEqual(type, std::string("promo_credit")))))) {
      direction = std::string("in");
    } else if (isTrue(
                   isTrue(isTrue(isTrue((isEqual(type,
                                                 std::string("withdrawal")))) ||
                                 isTrue((isEqual(
                                     type, std::string("commission"))))) ||
                          isTrue((isEqual(type, std::string("conversion"))))) ||
                   isTrue((isEqual(
                       type, std::string("perpetual_futures_funding")))))) {
      direction = std::string("out");
    }
    type = this->parseLedgerEntryType(type);
    std::any currencyId = this->safeString(item, std::string("asset_id"));
    std::any currenciesByNumericId =
        this->safeDict(this->options, std::string("currenciesByNumericId"));
    currency = this->safeValue(currenciesByNumericId, currencyId, currency);
    std::any code = (isTrue((isEqual(currency, std::any{})))
                         ? std::any(std::any{})
                         : std::any(::getValue(currency, std::string("code"))));
    std::any amount = this->safeString(item, std::string("amount"));
    std::any timestamp =
        this->parse8601(this->safeString(item, std::string("created_at")));
    std::any after = this->safeString(item, std::string("balance"));
    std::any before = ccxt::Precise::stringMax(
        std::string("0"), ccxt::Precise::stringSub(after, amount));
    std::any status = std::string("ok");
    return this->safeLedgerEntry(
        ccxt::dict{
            {std::string("info"), item},
            {std::string("id"), id},
            {std::string("direction"), direction},
            {std::string("account"), account},
            {std::string("referenceId"), referenceId},
            {std::string("referenceAccount"), referenceAccount},
            {std::string("type"), type},
            {std::string("currency"), code},
            {std::string("amount"), this->parseNumber(amount)},
            {std::string("before"), this->parseNumber(before)},
            {std::string("after"), this->parseNumber(after)},
            {std::string("status"), status},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("fee"), std::any{}},
        },
        currency);
  }

  /**
   * @method
   * @name delta#fetchDepositAddress
   * @description fetch the deposit address for a currency associated with this
   * account
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.network] unified network code
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<std::any>
  fetchDepositAddress(std::any code, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        awaitValue(this->loadMarkets());
                        std::any currency = this->currency(code);
                        std::any request = ccxt::dict{
                            {std::string("asset_symbol"),
                             ::getValue(currency, std::string("id"))},
                        };
                        std::any networkCode = this->safeStringUpper(
                            params, std::string("network"));
                        if (isTrue(!isEqual(networkCode, std::any{}))) {
                          ::setValue(request, std::string("network"),
                                     this->networkCodeToId(networkCode, code));
                          params = this->omit(params, std::string("network"));
                        }
                        std::any response =
                            awaitValue(this->privateGetDepositsAddress(
                                this->extend(request, params)));
                        //
                        //    {
                        //        "success": true,
                        //        "result": {
                        //            "id": 1915615,
                        //            "user_id": 27854758,
                        //            "address":
                        //            "TXYB4GdKsXKEWbeSNPsmGZu4ZVCkhVh1Zz",
                        //            "memo": "",
                        //            "status": "active",
                        //            "updated_at": "2023-01-12T06:03:46.000Z",
                        //            "created_at": "2023-01-12T06:03:46.000Z",
                        //            "asset_symbol": "USDT",
                        //            "network": "TRC20(TRON)",
                        //            "custodian": "fireblocks"
                        //        }
                        //    }
                        //
                        std::any result = this->safeDict(
                            response, std::string("result"), ccxt::dict{});
                        return this->parseDepositAddress(result, currency);
                      })
        .share();
  }

  std::any parseDepositAddress(std::any depositAddress,
                               std::any currency = std::any{}) override {
    //
    //    {
    //        "id": 1915615,
    //        "user_id": 27854758,
    //        "address": "TXYB4GdKsXKEWbeSNPsmGZu4ZVCkhVh1Zz",
    //        "memo": "",
    //        "status": "active",
    //        "updated_at": "2023-01-12T06:03:46.000Z",
    //        "created_at": "2023-01-12T06:03:46.000Z",
    //        "asset_symbol": "USDT",
    //        "network": "TRC20(TRON)",
    //        "custodian": "fireblocks"
    //    }
    //
    std::any address = this->safeString(depositAddress, std::string("address"));
    std::any marketId =
        this->safeString(depositAddress, std::string("asset_symbol"));
    std::any networkId =
        this->safeString(depositAddress, std::string("network"));
    std::any code = this->safeCurrencyCode(marketId, currency);
    this->checkAddress(address);
    return ccxt::dict{
        {std::string("info"), depositAddress},
        {std::string("currency"), code},
        {std::string("network"), this->networkIdToCode(networkId, code)},
        {std::string("address"), address},
        {std::string("tag"),
         this->safeString(depositAddress, std::string("memo"))},
    };
  }

