  /**
   * @method
   * @name delta#fetchLeverage
   * @description fetch the set leverage for a market
   * @see https://docs.delta.exchange/#get-order-leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [leverage structure]{@link
   * https://docs.ccxt.com/?id=leverage-structure}
   */
  std::shared_future<std::any>
  fetchLeverage(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        awaitValue(this->loadMarkets());
                        std::any market = this->market(symbol);
                        std::any request = ccxt::dict{
                            {std::string("product_id"),
                             ::getValue(market, std::string("numericId"))},
                        };
                        std::any response = awaitValue(
                            this->privateGetProductsProductIdOrdersLeverage(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "result": {
                        //             "index_symbol": null,
                        //             "leverage": "10",
                        //             "margin_mode": "isolated",
                        //             "order_margin": "0",
                        //             "product_id": 84,
                        //             "user_id": 30084879
                        //         },
                        //         "success": true
                        //     }
                        //
                        std::any result = this->safeDict(
                            response, std::string("result"), ccxt::dict{});
                        return this->parseLeverage(result, market);
                      })
        .share();
  }

  std::any parseLeverage(std::any leverage,
                         std::any market = std::any{}) override {
    std::any marketId = this->safeString(leverage, std::string("index_symbol"));
    std::any leverageValue =
        this->safeInteger(leverage, std::string("leverage"));
    return ccxt::dict{
        {std::string("info"), leverage},
        {std::string("symbol"), this->safeSymbol(marketId, market)},
        {std::string("marginMode"),
         this->safeStringLower(leverage, std::string("margin_mode"))},
        {std::string("longLeverage"), leverageValue},
        {std::string("shortLeverage"), leverageValue},
    };
  }

  /**
   * @method
   * @name delta#setLeverage
   * @description set the level of leverage for a market
   * @see https://docs.delta.exchange/#change-order-leverage
   * @param {float} leverage the rate of leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} response from the exchange
   */
  std::shared_future<std::any>
  setLeverage(std::any leverage, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " setLeverage() requires a symbol argument"))));
                 }
                 awaitValue(this->loadMarkets());
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("product_id"),
                      ::getValue(market, std::string("numericId"))},
                     {std::string("leverage"), leverage},
                 };
                 //
                 //     {
                 //         "result": {
                 //             "leverage": "20",
                 //             "margin_mode": "isolated",
                 //             "order_margin": "0",
                 //             "product_id": 84
                 //         },
                 //         "success": true
                 //     }
                 //
                 return awaitValue(
                     this->privatePostProductsProductIdOrdersLeverage(
                         this->extend(request, params)));
               })
        .share();
  }

  /**
   * @method
   * @name delta#fetchSettlementHistory
   * @description fetches historical settlement records
   * @see https://docs.delta.exchange/#get-product-settlement-prices
   * @param {string} symbol unified market symbol of the settlement history
   * @param {int} [since] timestamp in ms
   * @param {int} [limit] number of records
   * @param {object} [params] exchange specific params
   * @returns {object[]} a list of [settlement history objects]{@link
   * https://docs.ccxt.com/?id=settlement-history-structure}
   */
  virtual std::shared_future<std::any> fetchSettlementHistory(
      std::any symbol = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 awaitValue(this->loadMarkets());
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 std::any request = ccxt::dict{
                     {std::string("states"), std::string("expired")},
                 };
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("page_size"), limit);
                 }
                 std::any response = awaitValue(
                     this->publicGetProducts(this->extend(request, params)));
                 //
                 //     {
                 //         "result": [
                 //             {
                 //                 "contract_value": "0.001",
                 //                 "basis_factor_max_limit": "10.95",
                 //                 "maker_commission_rate": "0.0003",
                 //                 "launch_time": "2023-07-19T04:30:03Z",
                 //                 "trading_status": "operational",
                 //                 "product_specs": {
                 //                     "backup_vol_expiry_time": 31536000,
                 //                     "max_deviation_from_external_vol": 0.75,
                 //                     "max_lower_deviation_from_external_vol":
                 //                     0.75,
                 //                     "max_upper_deviation_from_external_vol":
                 //                     0.5, "max_volatility": 3,
                 //                     "min_volatility": 0.1,
                 //                     "premium_commission_rate": 0.1,
                 //                     "settlement_index_price":
                 //                     "29993.536675710806",
                 //                     "vol_calculation_method": "orderbook",
                 //                     "vol_expiry_time": 31536000
                 //                 },
                 //                 "description": "BTC call option expiring on
                 //                 19-7-2023", "settlement_price": "0",
                 //                 "disruption_reason": null,
                 //                 "settling_asset": {},
                 //                 "initial_margin": "1",
                 //                 "tick_size": "0.1",
                 //                 "maintenance_margin": "0.5",
                 //                 "id": 117542,
                 //                 "notional_type": "vanilla",
                 //                 "ui_config": {},
                 //                 "contract_unit_currency": "BTC",
                 //                 "symbol": "C-BTC-30900-190723",
                 //                 "insurance_fund_margin_contribution": "1",
                 //                 "price_band": "2",
                 //                 "annualized_funding": "10.95",
                 //                 "impact_size": 200,
                 //                 "contract_type": "call_options",
                 //                 "position_size_limit": 255633,
                 //                 "max_leverage_notional": "200000",
                 //                 "initial_margin_scaling_factor": "0.000002",
                 //                 "strike_price": "30900",
                 //                 "is_quanto": false,
                 //                 "settlement_time": "2023-07-19T12:00:00Z",
                 //                 "liquidation_penalty_factor": "0.5",
                 //                 "funding_method": "mark_price",
                 //                 "taker_commission_rate": "0.0003",
                 //                 "default_leverage":
                 //                 "100.000000000000000000", "state":
                 //                 "expired", "auction_start_time": null,
                 //                 "short_description": "BTC  Call",
                 //                 "quoting_asset": {},
                 //                 "maintenance_margin_scaling_factor":"0.000002"
                 //             }
                 //         ],
                 //         "success": true
                 //     }
                 //
                 std::any result = this->safeList(
                     response, std::string("result"), ccxt::list{});
                 std::any settlements = this->parseSettlements(result, market);
                 std::any sorted =
                     this->sortBy(settlements, std::string("timestamp"));
                 return this->filterBySymbolSinceLimit(
                     sorted, this->safeString(market, std::string("symbol")),
                     since, limit);
               })
        .share();
  }

  virtual std::any parseSettlement(std::any settlement, std::any market) {
    //
    //     {
    //         "contract_value": "0.001",
    //         "basis_factor_max_limit": "10.95",
    //         "maker_commission_rate": "0.0003",
    //         "launch_time": "2023-07-19T04:30:03Z",
    //         "trading_status": "operational",
    //         "product_specs": {
    //             "backup_vol_expiry_time": 31536000,
    //             "max_deviation_from_external_vol": 0.75,
    //             "max_lower_deviation_from_external_vol": 0.75,
    //             "max_upper_deviation_from_external_vol": 0.5,
    //             "max_volatility": 3,
    //             "min_volatility": 0.1,
    //             "premium_commission_rate": 0.1,
    //             "settlement_index_price": "29993.536675710806",
    //             "vol_calculation_method": "orderbook",
    //             "vol_expiry_time": 31536000
    //         },
    //         "description": "BTC call option expiring on 19-7-2023",
    //         "settlement_price": "0",
    //         "disruption_reason": null,
    //         "settling_asset": {},
    //         "initial_margin": "1",
    //         "tick_size": "0.1",
    //         "maintenance_margin": "0.5",
    //         "id": 117542,
    //         "notional_type": "vanilla",
    //         "ui_config": {},
    //         "contract_unit_currency": "BTC",
    //         "symbol": "C-BTC-30900-190723",
    //         "insurance_fund_margin_contribution": "1",
    //         "price_band": "2",
    //         "annualized_funding": "10.95",
    //         "impact_size": 200,
    //         "contract_type": "call_options",
    //         "position_size_limit": 255633,
    //         "max_leverage_notional": "200000",
    //         "initial_margin_scaling_factor": "0.000002",
    //         "strike_price": "30900",
    //         "is_quanto": false,
    //         "settlement_time": "2023-07-19T12:00:00Z",
    //         "liquidation_penalty_factor": "0.5",
    //         "funding_method": "mark_price",
    //         "taker_commission_rate": "0.0003",
    //         "default_leverage": "100.000000000000000000",
    //         "state": "expired",
    //         "auction_start_time": null,
    //         "short_description": "BTC  Call",
    //         "quoting_asset": {},
    //         "maintenance_margin_scaling_factor":"0.000002"
    //     }
    //
    std::any datetime =
        this->safeString(settlement, std::string("settlement_time"));
    std::any marketId = this->safeString(settlement, std::string("symbol"));
    return ccxt::dict{
        {std::string("info"), settlement},
        {std::string("symbol"), this->safeSymbol(marketId, market)},
        {std::string("price"),
         this->safeNumber(settlement, std::string("settlement_price"))},
        {std::string("timestamp"), this->parse8601(datetime)},
        {std::string("datetime"), datetime},
    };
  }

  virtual std::any parseSettlements(std::any settlements, std::any market) {
    std::any result = ccxt::list{};
    for (std::any i = 0; isLessThan(i, getArrayLength(settlements));
         postFixIncrement(i)) {
      arrayPush(result,
                this->parseSettlement(::getValue(settlements, i), market));
    }
    return result;
  }

